-- ============================================================================
--  Smart HR System — upgrade 2.0.0 -> 3.0.0
--  District -> Tehsil -> Department
--
--  Level 1  District     the district has tehsils
--  Level 2  Tehsil       the tehsil has departments
--  Level 3  Department   every department sits in a district, and in a tehsil
--                        unless it is at district headquarters
--
--  Every department carries an authority level:
--    district    covers the whole district   (e.g. Deputy Commissioner Office)
--    tehsil      covers its tehsil           (e.g. Assistant Commissioner Office)
--    department  covers only itself          (a single authority)
--
--  A user's access is the authority of their department. Only district- and
--  tehsil-level authorities publish service records; every officer signs.
--
--  The database itself now guarantees the chain is consistent: a department's
--  tehsil must belong to the department's district (composite foreign key),
--  a district-level department has no tehsil and a tehsil-level one has one
--  (CHECK), and nothing can point at a department, office or employee that
--  does not exist (foreign keys).
--
--  The old districts, tehsils and departments are replaced with the Province
--  of Punjab (generated by database/tools/punjab_geography.py). Existing
--  employees and their posting history are moved onto the new departments by
--  the office they are posted at; the old branch name is kept as the posting's
--  section so nothing is lost.
-- ============================================================================

SET FOREIGN_KEY_CHECKS = 0;

-- ------------------------------------------------ 1. SET THE OLD ONES ASIDE
DROP TABLE IF EXISTS departments_old, districts_old, tehsils_old;
RENAME TABLE departments TO departments_old, districts TO districts_old, tehsils TO tehsils_old;

-- --------------------------------------------------- 2. THE CHAIN ITSELF
CREATE TABLE districts (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  division    VARCHAR(80)  DEFAULT NULL,
  name        VARCHAR(120) NOT NULL,
  code        VARCHAR(20)  NOT NULL,
  description VARCHAR(255) DEFAULT NULL,
  sort_order  INT NOT NULL DEFAULT 0,
  is_active   TINYINT(1) NOT NULL DEFAULT 1,
  is_deleted  TINYINT(1) NOT NULL DEFAULT 0,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_district_name (name),
  UNIQUE KEY uq_district_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE tehsils (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  district_id INT UNSIGNED NOT NULL,
  name        VARCHAR(120) NOT NULL,
  code        VARCHAR(20)  NOT NULL,
  description VARCHAR(255) DEFAULT NULL,
  sort_order  INT NOT NULL DEFAULT 0,
  is_active   TINYINT(1) NOT NULL DEFAULT 1,
  is_deleted  TINYINT(1) NOT NULL DEFAULT 0,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_tehsil_name (district_id, name),
  UNIQUE KEY uq_tehsil_code (district_id, code),
  UNIQUE KEY uq_tehsil_in_district (id, district_id),      -- target of the departments composite key
  CONSTRAINT fk_tehsil_district FOREIGN KEY (district_id) REFERENCES districts (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE departments (
  id               INT UNSIGNED NOT NULL AUTO_INCREMENT,
  name             VARCHAR(160) NOT NULL,
  code             VARCHAR(20)  NOT NULL,
  level            ENUM('district','tehsil','department') NOT NULL DEFAULT 'department',
  district_id      INT UNSIGNED NOT NULL,
  tehsil_id        INT UNSIGNED DEFAULT NULL,               -- NULL = at district headquarters
  head_designation VARCHAR(120) DEFAULT NULL,               -- e.g. Deputy Commissioner
  address          VARCHAR(255) DEFAULT NULL,
  latitude         DECIMAL(10,7) DEFAULT NULL,
  longitude        DECIMAL(10,7) DEFAULT NULL,
  description      VARCHAR(255) DEFAULT NULL,
  sort_order       INT NOT NULL DEFAULT 0,
  is_active        TINYINT(1) NOT NULL DEFAULT 1,
  is_deleted       TINYINT(1) NOT NULL DEFAULT 0,
  created_at       DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       DATETIME DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_department_name (name),
  UNIQUE KEY uq_department_code (code),
  KEY idx_department_district (district_id, level),
  KEY idx_department_tehsil (tehsil_id, level),
  CONSTRAINT fk_department_district FOREIGN KEY (district_id) REFERENCES districts (id),
  -- the tehsil must be a tehsil OF this district
  CONSTRAINT fk_department_tehsil FOREIGN KEY (tehsil_id, district_id) REFERENCES tehsils (id, district_id),
  CONSTRAINT chk_department_level CHECK (
       (level = 'district'   AND tehsil_id IS NULL)
    OR (level = 'tehsil'     AND tehsil_id IS NOT NULL)
    OR (level = 'department')
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ------------------------------------------------- 3. PROVINCE OF PUNJAB
-- Generated by database/tools/punjab_geography.py — edit the generator, not this file.
-- Province of Punjab: 41 districts, 148 tehsils, 1100 departments.




-- ------------------------------------ 4. OFFICES BELONG TO A DEPARTMENT
-- Each existing office is placed under the department it belongs to: the AC
-- office of its tehsil, the Arazi Record Centre for the record centres, and
-- the DC office for everything at district headquarters.
-- Old tehsils and districts are matched to the new ones by name. A tehsil
-- name used in more than one district is matched within the same district.
DROP TEMPORARY TABLE IF EXISTS tehsil_map, district_map;
CREATE TEMPORARY TABLE district_map (old_id INT UNSIGNED PRIMARY KEY, new_id INT UNSIGNED)
SELECT od.id AS old_id, nd.id AS new_id FROM districts_old od LEFT JOIN districts nd ON nd.name = od.name;
CREATE TEMPORARY TABLE tehsil_map (old_id INT UNSIGNED PRIMARY KEY, new_id INT UNSIGNED)
SELECT ot.id AS old_id,
       COALESCE(
         (SELECT nt.id FROM tehsils nt WHERE nt.name = ot.name AND nt.district_id = dm.new_id LIMIT 1),
         (SELECT nt.id FROM tehsils nt WHERE nt.name = ot.name ORDER BY nt.id LIMIT 1)
       ) AS new_id
  FROM tehsils_old ot LEFT JOIN district_map dm ON dm.old_id = ot.district_id;

DROP TEMPORARY TABLE IF EXISTS loc_map;
CREATE TEMPORARY TABLE loc_map (loc_id INT UNSIGNED PRIMARY KEY, dept_id INT UNSIGNED NOT NULL);
SELECT l.id,
       COALESCE(
         CASE WHEN l.name IN ('Revenue Record Centre', 'Land Record Centre (Arazi)')
              THEN (SELECT id FROM departments WHERE code = 'NNS-NSH-ARC') END,
         (SELECT d.id FROM tehsil_map tm JOIN departments d ON d.tehsil_id = tm.new_id AND d.level = 'tehsil'
           WHERE tm.old_id = l.tehsil_id),
         (SELECT d.id FROM district_map dm JOIN departments d ON d.district_id = dm.new_id AND d.level = 'district'
           WHERE dm.old_id = l.district_id),
         (SELECT id FROM departments WHERE code = 'NNS-DC'))
  FROM posting_locations l;

UPDATE posting_locations l JOIN loc_map m ON m.loc_id = l.id SET l.department_id = m.dept_id;

-- an office's district and tehsil are those of its department — stored once
ALTER TABLE posting_locations
  DROP COLUMN district_id,
  DROP COLUMN tehsil_id,
  MODIFY department_id INT UNSIGNED NOT NULL;

-- ------------------------------------------------------- 5. POSTINGS
-- A posting belongs to the department of the office it was made to; the old
-- branch name (Revenue Branch, Accounts Branch ...) is kept as the section.
UPDATE postings p
  LEFT JOIN loc_map m          ON m.loc_id = p.location_id
  LEFT JOIN departments_old od ON od.id = p.department_id
   SET p.section       = COALESCE(NULLIF(p.section, ''), od.name),
       p.department_id = COALESCE(m.dept_id, (SELECT id FROM departments WHERE code = 'NNS-DC'));

-- ------------------------------------------------------ 6. EMPLOYEES
-- An employee belongs to the department of their current posting; their
-- tehsil and district follow from it and are no longer stored separately.
UPDATE employees e
  LEFT JOIN postings p ON p.id = e.current_posting_id
   SET e.department_id = COALESCE(p.department_id, (SELECT id FROM departments WHERE code = 'NNS-DC'));

ALTER TABLE employees DROP COLUMN district_id, DROP COLUMN tehsil_id;

-- ---------------------------------------------- 7. SANCTIONED POSTS
-- The old "departments" were branches of the DC office, so their sanctioned
-- strength is combined under the DC office.
DROP TEMPORARY TABLE IF EXISTS sp_merge;
CREATE TEMPORARY TABLE sp_merge AS
SELECT designation_id,
       MAX(pay_scale_id)     AS pay_scale_id,
       SUM(sanctioned_count) AS sanctioned_count,
       LEFT(GROUP_CONCAT(DISTINCT NULLIF(remarks, '') SEPARATOR '; '), 255) AS remarks
  FROM sanctioned_posts WHERE is_deleted = 0 GROUP BY designation_id;
DELETE FROM sanctioned_posts;
SELECT (SELECT id FROM departments WHERE code = 'NNS-DC'), designation_id, pay_scale_id, sanctioned_count, remarks, 1
  FROM sp_merge;

-- ---------------------------------------------------------- 8. USERS
-- An officer belongs to a department; their reach is that department's level.
ALTER TABLE users
  ADD COLUMN department_id INT UNSIGNED DEFAULT NULL AFTER employee_id,
  ADD KEY idx_users_department (department_id);

-- a DC becomes an officer of the DC office of their own district
UPDATE users u
  JOIN roles r        ON r.id = u.role_id AND r.name = 'dc'
  JOIN district_map dm ON dm.old_id = u.district_id
  JOIN departments d  ON d.district_id = dm.new_id AND d.level = 'district'
   SET u.department_id = d.id;

-- an AC becomes an officer of the AC office of their own tehsil
UPDATE users u
  JOIN roles r       ON r.id = u.role_id AND r.name = 'ac'
  JOIN tehsil_map tm ON tm.old_id = u.tehsil_id
  JOIN departments d ON d.tehsil_id = tm.new_id AND d.level = 'tehsil'
   SET u.department_id = d.id;
-- An AC account that had no tehsil keeps no department: it sees nothing
-- until one is chosen in Users & Roles (the page flags it).

ALTER TABLE users DROP COLUMN district_id, DROP COLUMN tehsil_id;

-- ---------------------------------------------------------- 9. ROLES
-- DC and AC are no longer separate roles: an officer's authority is the
-- level of their department (district / tehsil / department).
UPDATE users SET role_id = 2 WHERE role_id = 4;
DELETE FROM roles WHERE id = 4;
UPDATE roles SET name = 'officer', label = 'Officer' WHERE id = 2;
DROP TABLE IF EXISTS user_departments;

-- ------------------------------------------------ 10. OLD GEOGRAPHY GOES
DROP TABLE departments_old, districts_old, tehsils_old;
DROP TEMPORARY TABLE IF EXISTS loc_map, sp_merge, tehsil_map, district_map;

-- -------------------------------------------- 11. REFERENTIAL INTEGRITY
ALTER TABLE posting_locations ADD CONSTRAINT fk_location_department FOREIGN KEY (department_id) REFERENCES departments (id);
ALTER TABLE employees         ADD CONSTRAINT fk_employee_department FOREIGN KEY (department_id) REFERENCES departments (id);
ALTER TABLE sanctioned_posts  ADD CONSTRAINT fk_sanction_department FOREIGN KEY (department_id) REFERENCES departments (id);
ALTER TABLE users
  ADD CONSTRAINT fk_user_department FOREIGN KEY (department_id) REFERENCES departments (id),
  ADD CONSTRAINT fk_user_employee   FOREIGN KEY (employee_id)   REFERENCES employees (id);
ALTER TABLE postings
  ADD CONSTRAINT fk_posting_employee   FOREIGN KEY (employee_id)   REFERENCES employees (id),
  ADD CONSTRAINT fk_posting_department FOREIGN KEY (department_id) REFERENCES departments (id),
  ADD CONSTRAINT fk_posting_location   FOREIGN KEY (location_id)   REFERENCES posting_locations (id);

-- every service record, and everything filed against an employee
ALTER TABLE promotions         ADD CONSTRAINT fk_promotion_employee     FOREIGN KEY (employee_id) REFERENCES employees (id);
ALTER TABLE increments         ADD CONSTRAINT fk_increment_employee     FOREIGN KEY (employee_id) REFERENCES employees (id);
ALTER TABLE leaves             ADD CONSTRAINT fk_leave_employee         FOREIGN KEY (employee_id) REFERENCES employees (id);
ALTER TABLE awards             ADD CONSTRAINT fk_award_employee         FOREIGN KEY (employee_id) REFERENCES employees (id);
ALTER TABLE punishments        ADD CONSTRAINT fk_punishment_employee    FOREIGN KEY (employee_id) REFERENCES employees (id);
ALTER TABLE reinstatements     ADD CONSTRAINT fk_reinstatement_employee FOREIGN KEY (employee_id) REFERENCES employees (id);
ALTER TABLE deputations        ADD CONSTRAINT fk_deputation_employee    FOREIGN KEY (employee_id) REFERENCES employees (id);
ALTER TABLE exits              ADD CONSTRAINT fk_exit_employee          FOREIGN KEY (employee_id) REFERENCES employees (id);
ALTER TABLE rejoinings         ADD CONSTRAINT fk_rejoining_employee     FOREIGN KEY (employee_id) REFERENCES employees (id);
ALTER TABLE inquiries          ADD CONSTRAINT fk_inquiry_employee       FOREIGN KEY (employee_id) REFERENCES employees (id);
ALTER TABLE timeline_events    ADD CONSTRAINT fk_timeline_employee      FOREIGN KEY (employee_id) REFERENCES employees (id);
ALTER TABLE employee_family    ADD CONSTRAINT fk_family_employee        FOREIGN KEY (employee_id) REFERENCES employees (id);
ALTER TABLE employee_documents ADD CONSTRAINT fk_document_employee      FOREIGN KEY (employee_id) REFERENCES employees (id);
ALTER TABLE notification_log   ADD CONSTRAINT fk_notification_employee  FOREIGN KEY (employee_id) REFERENCES employees (id);

SET FOREIGN_KEY_CHECKS = 1;
